// Domain 3 — Security Architecture. Original flashcards (sources as in lessons.js).
let n = 0;
const c = (topic, front, back) => ({ id: `d3-f${String(++n).padStart(3, '0')}`, topic, front, back });

export default [
  c('3.1', 'The four NIST SP 800-145 cloud deployment models?', 'Public (open use), private (one organization), community (several organizations with shared concerns), hybrid (two or more distinct infrastructures bound together).'),
  c('3.1', 'Deployment model vs service model?', 'Deployment = who the infrastructure is for and where it runs (public, private, community, hybrid). Service = which layers the provider manages (IaaS, PaaS, SaaS).'),
  c('3.1', 'Hybrid vs multicloud?', 'Hybrid: two or more distinct cloud infrastructures (e.g., private + public) bound for portability. Multicloud: using more than one cloud provider.'),
  c('3.1', 'Shared responsibility: what never moves to the provider?', 'Your data, its classification, and who can access it (accounts, permissions, MFA). The physical layer of public cloud is always the provider\'s.'),
  c('3.1', 'Serverless: what shifts to the provider, what stays?', 'Provider: OS and runtime patching, servers, scaling. Customer: function code, libraries, IAM permissions, event validation, secrets, logging.'),
  c('3.1', 'IaC security pros and cons?', 'Pros: consistency, code review, pre-deployment scanning, drift detection. Cons: mistakes replicate everywhere; secrets in code/state; the pipeline becomes a prime target.'),
  c('3.1', 'OT priorities (SP 800-82 Rev. 3)?', 'Integrity and availability first, with safety as the overarching priority; patching and reboots need planned outages, so compensating controls matter.'),
  c('3.1', 'Air gap (NIST/RFC 4949)?', 'Systems not physically connected, and any logical connection is manual only. Limits: removable media, insiders, manual patching, quiet erosion.'),
  c('3.1', 'Logical vs physical segmentation?', 'Logical: VLANs, VRFs, zones, security groups on shared gear (depends on correct config). Physical: separate hardware and cabling (holds even if network gear fails).'),
  c('3.1', 'Data sovereignty vs residency vs localization?', 'Sovereignty: which jurisdiction\'s laws apply. Residency: where data physically sits. Localization: a legal requirement to keep it in-country.'),
  c('3.2', 'Where does a public web server go? A database with customer data?', 'Web server (or reverse proxy): screened subnet (DMZ). Database: restricted data zone reachable only from app tiers.'),
  c('3.2', 'IPS vs IDS placement?', 'IPS inline (traffic passes through it) to block. IDS on a SPAN port or TAP: detects and alerts only.'),
  c('3.2', 'Fail-open vs fail-closed?', 'Fail-open: allows traffic when the control fails (availability). Fail-closed: blocks it (confidentiality/integrity). Firewalls fail closed.'),
  c('3.2', 'Fail-safe vs fail-secure door lock?', 'Fail-safe: unlocks on power loss (exit routes, life safety). Fail-secure: stays locked (server rooms), with mechanical free egress.'),
  c('3.2', 'SP 800-207: PE, PA, PDP, PEP?', 'PE decides and logs; PA executes by setting up or tearing down the path; PE + PA = PDP; PEP enables, monitors and terminates connections.'),
  c('3.2', 'Zero Trust device management?', 'Inventory (know every device; unknown = untrusted) and health/posture (patches, EDR, encryption), reported by CDM and fed to the policy engine.'),
  c('3.2', 'Full tunnel vs split tunnel?', 'Full: all client traffic through the VPN (corporate inspection applies). Split: only corporate prefixes through the VPN; internet traffic goes direct.'),
  c('3.2', 'Which tunnels do not encrypt by themselves?', 'GRE (RFC 2784) and L2TP (RFC 2661/3931). Run them inside IPsec when confidentiality is needed.'),
  c('3.2', 'End-to-end encrypted messaging: security effect?', 'Only endpoints hold keys; the provider and network inspection cannot read content. Controls shift to managed endpoints; metadata may remain visible.'),
  c('3.2', 'Out-of-band management?', 'Separate path for device management (console servers, management network, cellular or separate circuit). Works when production is down; lock it down tightly.'),
  c('3.2', 'SSE vs SASE?', 'SSE: cloud-delivered security (SWG, CASB, ZTNA, often FWaaS, DLP). SASE = SSE + WAN networking such as SD-WAN.'),
  c('3.2', 'gMSA?', 'AD service account whose password Windows computes and rotates (30 days by default); usable by multiple servers named in PrincipalsAllowedToRetrieveManagedPassword. sMSA = one computer.'),
  c('3.2', 'Privilege creep?', 'Gradual build-up of access beyond the current role (old roles, never-removed temporary grants). Fix: mover process, role-based access, access reviews.'),
  c('3.3', 'Structured vs unstructured data?', 'Structured: fixed schema (database tables). Unstructured: no data model (documents, email, chat, images); needs content inspection to classify.'),
  c('3.3', 'Protecting data in use?', 'Access control, masking on display, memory protections and confidential computing (hardware TEEs/secure enclaves).'),
  c('3.3', 'EO 13526 classification levels?', 'Top secret (exceptionally grave damage), secret (serious damage), confidential (damage) to national security.'),
  c('3.3', 'What does "critical" classify?', 'Importance to operations (availability and integrity), not secrecy. Public data can be critical.'),
  c('3.3', 'Tokenization vs encryption?', 'Encryption: reversible by anyone with the key. Tokenization (vault model): random substitute, reversible only through the token vault that holds the mapping.'),
  c('3.3', 'Data transpose?', 'Protecting data by rearranging the order or position of its elements (transposition, swapping values); reversible if the pattern is known.'),
  c('3.3', 'Pseudonymization vs anonymization (GDPR)?', 'Pseudonymized: re-identifiable with separately kept information; still personal data (Recital 26). Anonymized: irreversibly unlinked; outside the GDPR.'),
  c('3.3', 'Owner vs steward vs custodian?', 'Owner: accountable, decides classification and access. Steward: data quality, definitions, policy compliance. Custodian: implements controls (storage, encryption, backups).'),
  c('3.3', 'Controller vs processor vs subprocessor?', 'Controller decides purposes and means; processor processes on its behalf; subprocessor is "another processor" engaged by the processor with the controller\'s authorization (GDPR Art. 28).'),
  c('3.3', 'Sanitizing SSDs (SP 800-88 Rev. 2)?', 'Overwriting gives little assurance on SSDs; use purge (sanitize command, cryptographic erase) or destroy. Never degauss SSDs.'),
  c('3.4', 'Hot vs warm vs cold site?', 'Cold: space and power only (days to weeks). Warm: equipment, no current data or software (hours to days). Hot: running, data current (minutes to hours).'),
  c('3.4', 'UPS vs generator?', 'UPS: instant battery power for minutes and power conditioning; bridges until the generator, which takes seconds to start and runs for hours or days.'),
  c('3.4', 'Incremental vs differential restore?', 'Incremental: last full + every incremental since, in order. Differential: last full + latest differential only.'),
  c('3.4', '3-2-1 rule?', '3 copies (primary + 2 backups), on 2 different media types, 1 copy offsite (CISA). Add an immutable or offline copy against ransomware.'),
  c('3.4', 'Simulation vs parallel processing vs failover test?', 'Simulation: staged scenario, production untouched. Parallel: alternate runs alongside primary, outputs compared. Failover: production actually switches.'),
  c('3.4', 'RTO vs RPO?', 'RTO: maximum time a system can be down. RPO: maximum data loss, measured back from the disruption. Both are business targets.'),
  c('3.4', 'Availability formula?', '`MTBF / (MTBF + MTTR)`. Example: 2,920 / (2,920 + 5) = 99.83%.'),
];
